```turtle
@prefix ea: <http://example.org/onto/assessment#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/assessment>
    a owl:Ontology ;
    rdfs:label "Educational Assessment Ontology"@en ;
    rdfs:comment "An ontology formalizing educational assessment concepts, classification axes, measurement qualities, and evaluation instruments based on the provided corpus."@en .

#################################################################
#    Root Domain Class
#################################################################

ea:EducationalMeasurementEntity
    a owl:Class ;
    rdfs:subClassOf owl:Thing ;
    rdfs:label "Educational Measurement Entity"@en .

#################################################################
#    Assessment Core Classes
#################################################################

ea:Assessment
    a owl:Class ;
    rdfs:subClassOf ea:EducationalMeasurementEntity ;
    rdfs:label "Assessment"@en ;
    skos:altLabel "Educational Assessment"@en , "Educational Evaluation"@en .

ea:Test
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Test"@en ;
    skos:altLabel "Evaluation"@en , "Exam"@en , "Examination"@en .

#################################################################
#    Axis Reification: Assessment Purpose
#################################################################

ea:hasPurpose
    a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ;
    rdfs:range ea:PurposeCategory ;
    owl:inverseOf ea:isPurposeOf ;
    rdfs:label "has purpose"@en .

ea:isPurposeOf
    a owl:ObjectProperty ;
    rdfs:domain ea:PurposeCategory ;
    rdfs:range ea:Assessment ;
    rdfs:label "is purpose of"@en .

ea:PurposeCategory
    a owl:Class ;
    rdfs:subClassOf ea:EducationalMeasurementEntity ;
    owl:disjointUnionOf (
        ea:DiagnosticPurpose
        ea:FormativePurpose
        ea:InterimPurpose
        ea:PlacementPurpose
        ea:ScreeningPurpose
        ea:SummativePurpose
    ) ;
    rdfs:label "Purpose Category"@en .

ea:DiagnosticPurpose
    a owl:Class ;
    rdfs:subClassOf ea:PurposeCategory ;
    rdfs:label "Diagnostic Purpose"@en .

ea:FormativePurpose
    a owl:Class ;
    rdfs:subClassOf ea:PurposeCategory ;
    rdfs:label "Formative Purpose"@en .

ea:InterimPurpose
    a owl:Class ;
    rdfs:subClassOf ea:PurposeCategory ;
    rdfs:label "Interim Purpose"@en .

ea:PlacementPurpose
    a owl:Class ;
    rdfs:subClassOf ea:PurposeCategory ;
    rdfs:label "Placement Purpose"@en .

ea:ScreeningPurpose
    a owl:Class ;
    rdfs:subClassOf ea:PurposeCategory ;
    rdfs:label "Screening Purpose"@en .

ea:SummativePurpose
    a owl:Class ;
    rdfs:subClassOf ea:PurposeCategory ;
    rdfs:label "Summative Purpose"@en .

ea:DiagnosticAssessment
    a owl:Class ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:DiagnosticPurpose ]
        )
    ] ;
    rdfs:subClassOf ea:Assessment , ea:FormativeAssessment ;
    rdfs:label "Diagnostic Assessment"@en ;
    skos:altLabel "Diagnostic Testing"@en ;
    rdfs:comment "Classification tension in corpus: one passage classifies diagnostic assessment as a coordinate alternative alongside placement, formative, and summative assessments; another passage states that diagnostic assessment is a common form of formative assessment. Both axioms are asserted."@en .

ea:FormativeAssessment
    a owl:Class ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:FormativePurpose ]
        )
    ] ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Formative Assessment"@en ;
    skos:altLabel "Assessment for Learning"@en , "Classroom Assessment"@en , "Educative Assessment"@en , "Formative Evaluation"@en , "Formative Feedback"@en .

ea:InterimAssessment
    a owl:Class ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:InterimPurpose ]
        )
    ] ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Interim Assessment"@en ;
    skos:altLabel "Benchmark Assessment"@en , "Benchmark Test"@en ;
    rdfs:comment "The corpus notes a debate: some educators consider interim tests to be formative because they are used diagnostically to inform instructional adjustments, while others consider them summative."@en .

ea:PlacementAssessment
    a owl:Class ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:PlacementPurpose ]
        )
    ] ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Placement Assessment"@en ;
    skos:altLabel "Initial Assessment"@en , "Placement Evaluation"@en , "Pre-Assessment"@en , "Threshold Knowledge Test"@en .

ea:ScreeningAssessment
    a owl:Class ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:ScreeningPurpose ]
        )
    ] ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Screening Assessment"@en ;
    skos:altLabel "Screening Test"@en .

ea:SummativeAssessment
    a owl:Class ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:SummativePurpose ]
        )
    ] ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Summative Assessment"@en ;
    skos:altLabel "Assessment of Learning"@en , "Summative Evaluation"@en .

#################################################################
#    Axis Reification: Referencing Framework
#################################################################

ea:hasReferencingFramework
    a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ;
    rdfs:range ea:ReferencingFramework ;
    owl:inverseOf ea:isReferencingFrameworkOf ;
    rdfs:label "has referencing framework"@en .

ea:isReferencingFrameworkOf
    a owl:ObjectProperty ;
    rdfs:domain ea:ReferencingFramework ;
    rdfs:range ea:Assessment ;
    rdfs:label "is referencing framework of"@en .

ea:ReferencingFramework
    a owl:Class ;
    rdfs:subClassOf ea:EducationalMeasurementEntity ;
    owl:disjointUnionOf (
        ea:CriterionReferencing
        ea:IpsativeReferencing
        ea:NormReferencing
    ) ;
    rdfs:label "Referencing Framework"@en .

ea:CriterionReferencing
    a owl:Class ;
    rdfs:subClassOf ea:ReferencingFramework ;
    rdfs:label "Criterion Referencing"@en .

ea:IpsativeReferencing
    a owl:Class ;
    rdfs:subClassOf ea:ReferencingFramework ;
    rdfs:label "Ipsative Referencing"@en .

ea:NormReferencing
    a owl:Class ;
    rdfs:subClassOf ea:ReferencingFramework ;
    rdfs:label "Norm Referencing"@en .

ea:CriterionReferencedAssessment
    a owl:Class ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasReferencingFramework ; owl:someValuesFrom ea:CriterionReferencing ]
        )
    ] ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Criterion-Referenced Assessment"@en ;
    skos:altLabel "CRT"@en , "Criterion-Referenced Test"@en , "Standards-Based Assessment"@en , "Standards-Referenced Assessment"@en .

ea:NormReferencedAssessment
    a owl:Class ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasReferencingFramework ; owl:someValuesFrom ea:NormReferencing ]
        )
    ] ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Norm-Referenced Assessment"@en ;
    skos:altLabel "NRT"@en , "Norm-Referenced Test"@en , "Normative Assessment"@en .

ea:IpsativeAssessment
    a owl:Class ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasReferencingFramework ; owl:someValuesFrom ea:IpsativeReferencing ]
        )
    ] ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Ipsative Assessment"@en ;
    skos:altLabel "Forced-Choice Assessment"@en .

#################################################################
#    Axis Reification: Objectivity
#################################################################

ea:hasObjectivityType
    a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ;
    rdfs:range ea:ObjectivityType ;
    owl:inverseOf ea:isObjectivityTypeOf ;
    rdfs:label "has objectivity type"@en .

ea:isObjectivityTypeOf
    a owl:ObjectProperty ;
    rdfs:domain ea:ObjectivityType ;
    rdfs:range ea:Assessment ;
    rdfs:label "is objectivity type of"@en .

ea:ObjectivityType
    a owl:Class ;
    rdfs:subClassOf ea:EducationalMeasurementEntity ;
    owl:disjointUnionOf (
        ea:ObjectiveAssessmentType
        ea:SubjectiveAssessmentType
    ) ;
    rdfs:label "Objectivity Type"@en .

ea:ObjectiveAssessmentType
    a owl:Class ;
    rdfs:subClassOf ea:ObjectivityType ;
    rdfs:label "Objective Assessment Type"@en .

ea:SubjectiveAssessmentType
    a owl:Class ;
    rdfs:subClassOf ea:ObjectivityType ;
    rdfs:label "Subjective Assessment Type"@en .

ea:ObjectiveAssessment
    a owl:Class ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasObjectivityType ; owl:someValuesFrom ea:ObjectiveAssessmentType ]
        )
    ] ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Objective Assessment"@en .

ea:SubjectiveAssessment
    a owl:Class ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasObjectivityType ; owl:someValuesFrom ea:SubjectiveAssessmentType ]
        )
    ] ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Subjective Assessment"@en .

#################################################################
#    Axis Reification: Formality
#################################################################

ea:hasFormalityType
    a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ;
    rdfs:range ea:FormalityType ;
    owl:inverseOf ea:isFormalityTypeOf ;
    rdfs:label "has formality type"@en .

ea:isFormalityTypeOf
    a owl:ObjectProperty ;
    rdfs:domain ea:FormalityType ;
    rdfs:range ea:Assessment ;
    rdfs:label "is formality type of"@en .

ea:FormalityType
    a owl:Class ;
    rdfs:subClassOf ea:EducationalMeasurementEntity ;
    owl:disjointUnionOf (
        ea:FormalAssessmentType
        ea:InformalAssessmentType
    ) ;
    rdfs:label "Formality Type"@en .

ea:FormalAssessmentType
    a owl:Class ;
    rdfs:subClassOf ea:FormalityType ;
    rdfs:label "Formal Assessment Type"@en .

ea:InformalAssessmentType
    a owl:Class ;
    rdfs:subClassOf ea:FormalityType ;
    rdfs:label "Informal Assessment Type"@en .

ea:FormalAssessment
    a owl:Class ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasFormalityType ; owl:someValuesFrom ea:FormalAssessmentType ]
        )
    ] ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Formal Assessment"@en ;
    skos:altLabel "Formal Test"@en .

ea:InformalAssessment
    a owl:Class ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasFormalityType ; owl:someValuesFrom ea:InformalAssessmentType ]
        )
    ] ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Informal Assessment"@en ;
    skos:altLabel "Informal Test"@en .

#################################################################
#    Axis Reification: Origin / Setting Agency
#################################################################

ea:hasOriginType
    a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ;
    rdfs:range ea:OriginType ;
    owl:inverseOf ea:isOriginTypeOf ;
    rdfs:label "has origin type"@en .

ea:isOriginTypeOf
    a owl:ObjectProperty ;
    rdfs:domain ea:OriginType ;
    rdfs:range ea:Assessment ;
    rdfs:label "is origin type of"@en .

ea:OriginType
    a owl:Class ;
    rdfs:subClassOf ea:EducationalMeasurementEntity ;
    owl:disjointUnionOf (
        ea:ExternalAssessmentType
        ea:InternalAssessmentType
    ) ;
    rdfs:label "Origin Type"@en .

ea:ExternalAssessmentType
    a owl:Class ;
    rdfs:subClassOf ea:OriginType ;
    rdfs:label "External Assessment Type"@en .

ea:InternalAssessmentType
    a owl:Class ;
    rdfs:subClassOf ea:OriginType ;
    rdfs:label "Internal Assessment Type"@en .

ea:InternalAssessment
    a owl:Class ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasOriginType ; owl:someValuesFrom ea:InternalAssessmentType ]
        )
    ] ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Internal Assessment"@en .

ea:ExternalAssessment
    a owl:Class ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasOriginType ; owl:someValuesFrom ea:ExternalAssessmentType ]
        )
    ] ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "External Assessment"@en .

#################################################################
#    Axis Reification: Stakes Level
#################################################################

ea:hasStakesLevel
    a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ;
    rdfs:range ea:StakesLevel ;
    owl:inverseOf ea:isStakesLevelOf ;
    rdfs:label "has stakes level"@en .

ea:isStakesLevelOf
    a owl:ObjectProperty ;
    rdfs:domain ea:StakesLevel ;
    rdfs:range ea:Assessment ;
    rdfs:label "is stakes level of"@en .

ea:StakesLevel
    a owl:Class ;
    rdfs:subClassOf ea:EducationalMeasurementEntity ;
    owl:disjointUnionOf (
        ea:HighStakes
        ea:LowStakes
    ) ;
    rdfs:label "Stakes Level"@en .

ea:HighStakes
    a owl:Class ;
    rdfs:subClassOf ea:StakesLevel ;
    rdfs:label "High Stakes"@en .

ea:LowStakes
    a owl:Class ;
    rdfs:subClassOf ea:StakesLevel ;
    rdfs:label "Low Stakes"@en .

ea:HighStakesAssessment
    a owl:Class ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasStakesLevel ; owl:someValuesFrom ea:HighStakes ]
        )
    ] ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "High-Stakes Assessment"@en ;
    skos:altLabel "High-Stakes Test"@en .

ea:LowStakesAssessment
    a owl:Class ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasStakesLevel ; owl:someValuesFrom ea:LowStakes ]
        )
    ] ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Low-Stakes Assessment"@en ;
    skos:altLabel "Low-Stakes Test"@en .

#################################################################
#    Axis Reification: Standardization Status
#################################################################

ea:hasStandardizationStatus
    a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ;
    rdfs:range ea:StandardizationStatus ;
    owl:inverseOf ea:isStandardizationStatusOf ;
    rdfs:label "has standardization status"@en .

ea:isStandardizationStatusOf
    a owl:ObjectProperty ;
    rdfs:domain ea:StandardizationStatus ;
    rdfs:range ea:Assessment ;
    rdfs:label "is standardization status of"@en .

ea:StandardizationStatus
    a owl:Class ;
    rdfs:subClassOf ea:EducationalMeasurementEntity ;
    owl:disjointUnionOf (
        ea:NonStandardizedStatus
        ea:StandardizedStatus
    ) ;
    rdfs:label "Standardization Status"@en .

ea:NonStandardizedStatus
    a owl:Class ;
    rdfs:subClassOf ea:StandardizationStatus ;
    rdfs:label "Non-Standardized Status"@en .

ea:StandardizedStatus
    a owl:Class ;
    rdfs:subClassOf ea:StandardizationStatus ;
    rdfs:label "Standardized Status"@en .

ea:StandardizedAssessment
    a owl:Class ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasStandardizationStatus ; owl:someValuesFrom ea:StandardizedStatus ]
        )
    ] ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Standardized Assessment"@en ;
    skos:altLabel "Standardized Test"@en .

ea:NonStandardizedAssessment
    a owl:Class ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasStandardizationStatus ; owl:someValuesFrom ea:NonStandardizedStatus ]
        )
    ] ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Non-Standardized Assessment"@en ;
    skos:altLabel "Non-Standardized Test"@en .

#################################################################
#    Specific Assessment Categories
#################################################################

ea:AuthenticAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Authentic Assessment"@en .

ea:PerformanceAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Performance Assessment"@en ;
    skos:altLabel "Performance Test"@en , "Performance-Based Assessment"@en .

ea:ProductPerformanceAssessment
    a owl:Class ;
    rdfs:subClassOf ea:PerformanceAssessment ;
    rdfs:label "Product Performance Assessment"@en .

ea:DemonstrationPerformanceAssessment
    a owl:Class ;
    rdfs:subClassOf ea:PerformanceAssessment ;
    rdfs:label "Demonstration Performance Assessment"@en .

ea:PortfolioAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Portfolio Assessment"@en ;
    skos:altLabel "Portfolio-Based Assessment"@en .

ea:ContinuousAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Continuous Assessment"@en .

ea:CommonAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Common Assessment"@en .

ea:CompetitiveExamination
    a owl:Class ;
    rdfs:subClassOf ea:HighStakesAssessment , ea:NormReferencedAssessment ;
    rdfs:label "Competitive Examination"@en ;
    skos:altLabel "Competitive Exam"@en .

ea:ForwardLookingAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Forward-Looking Assessment"@en .

ea:SelfAssessment
    a owl:Class ;
    rdfs:subClassOf ea:DiagnosticAssessment ;
    rdfs:label "Self-Assessment"@en ;
    skos:altLabel "Self-Evaluation"@en .

ea:PeerAssessment
    a owl:Class ;
    rdfs:subClassOf ea:FormativeAssessment ;
    rdfs:label "Peer Assessment"@en ;
    skos:altLabel "Peer Evaluation"@en .

ea:MidtermExamination
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Midterm Examination"@en ;
    skos:altLabel "Midterm Exam"@en .

ea:FinalExamination
    a owl:Class ;
    rdfs:subClassOf ea:SummativeAssessment ;
    rdfs:label "Final Examination"@en ;
    skos:altLabel "Final Exam"@en , "Finals"@en .

ea:Quiz
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Quiz"@en .

ea:WrittenAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Written Assessment"@en ;
    skos:altLabel "Written Test"@en .

ea:OralAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Oral Assessment"@en ;
    skos:altLabel "Oral Test"@en .

ea:PracticalAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Practical Assessment"@en ;
    skos:altLabel "Practical Test"@en .

ea:ComputerBasedAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Computer-Based Assessment"@en ;
    skos:altLabel "Electronic Exam"@en , "Online Assessment"@en , "eExam"@en .

ea:ComputerAdaptiveAssessment
    a owl:Class ;
    rdfs:subClassOf ea:ComputerBasedAssessment ;
    rdfs:label "Computer-Adaptive Assessment"@en ;
    skos:altLabel "Computer-Adaptive Test"@en .

#################################################################
#    Assessment Items and Components
#################################################################

ea:AssessmentItem
    a owl:Class ;
    rdfs:subClassOf ea:EducationalMeasurementEntity ;
    rdfs:label "Assessment Item"@en ;
    skos:altLabel "Item"@en , "Question"@en , "Test Question"@en .

ea:ObjectiveItem
    a owl:Class ;
    rdfs:subClassOf ea:AssessmentItem ;
    owl:disjointWith ea:SubjectiveItem ;
    rdfs:label "Objective Item"@en ;
    skos:altLabel "Objective Question"@en .

ea:SubjectiveItem
    a owl:Class ;
    rdfs:subClassOf ea:AssessmentItem ;
    rdfs:label "Subjective Item"@en ;
    skos:altLabel "Subjective Question"@en .

ea:MultipleChoiceItem
    a owl:Class ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:ObjectiveItem
            [ a owl:Restriction ; owl:onProperty ea:hasItemStem ; owl:someValuesFrom ea:ItemStem ]
            [ a owl:Restriction ; owl:onProperty ea:hasAnswerKey ; owl:qualifiedCardinality "1"^^xsd:nonNegativeInteger ; owl:onClass ea:AnswerKey ]
            [ a owl:Restriction ; owl:onProperty ea:hasDistractor ; owl:someValuesFrom ea:Distractor ]
        )
    ] ;
    rdfs:subClassOf ea:ObjectiveItem ;
    rdfs:label "Multiple Choice Item"@en ;
    skos:altLabel "MCQ"@en , "Multiple Choice Question"@en , "Objective Response"@en .

ea:MultipleResponseItem
    a owl:Class ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:ObjectiveItem
            [ a owl:Restriction ; owl:onProperty ea:hasItemStem ; owl:someValuesFrom ea:ItemStem ]
            [ a owl:Restriction ; owl:onProperty ea:hasAnswerKey ; owl:minQualifiedCardinality "2"^^xsd:nonNegativeInteger ; owl:onClass ea:AnswerKey ]
        )
    ] ;
    rdfs:subClassOf ea:ObjectiveItem ;
    rdfs:label "Multiple Response Item"@en ;
    skos:altLabel "Multiple Response Question"@en .

ea:TrueFalseItem
    a owl:Class ;
    rdfs:subClassOf ea:MultipleChoiceItem ;
    rdfs:label "True-False Item"@en ;
    skos:altLabel "True/False Question"@en .

ea:OneBestAnswerItem
    a owl:Class ;
    rdfs:subClassOf ea:MultipleChoiceItem ;
    rdfs:label "One-Best-Answer Item"@en ;
    skos:altLabel "One-Best-Answer Question"@en , "Single Best Answer"@en .

ea:MatchingItem
    a owl:Class ;
    rdfs:subClassOf ea:ObjectiveItem ;
    rdfs:label "Matching Item"@en ;
    skos:altLabel "Matching Question"@en .

ea:FillInTheBlankItem
    a owl:Class ;
